const isBlank = v => v === undefined || v === null || String(v).trim() === '';
const text = v => isBlank(v) ? null : String(v).trim();
const upper = v => {
  const t = text(v);
  return t ? t.toUpperCase() : null;
};
const bool = v => {
  if (isBlank(v)) return null;
  const t = String(v).trim().toLowerCase();
  if (['true','1','si','sí','yes','y'].includes(t)) return true;
  if (['false','0','no','n'].includes(t)) return false;
  return null;
};
const int = v => isBlank(v) ? null : Number.parseInt(String(v).replace(/[^0-9-]/g, ''), 10);
const num = v => isBlank(v) ? null : Number(String(v).replace(',', '.'));
const date = v => {
  const t = text(v);
  if (!t || ['NO HAY','BUSCAR'].includes(t.toUpperCase())) return null;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(t)) {
    const [d,m,y] = t.split('/');
    return `${y}-${m}-${d}`;
  }
  return t;
};
const nivel = v => {
  const t = upper(v);
  return ['P1','P2','P3','I1'].includes(t) ? t : 'P1';
};
const objetivo = v => {
  const t = upper(v);
  if (!t) return null;
  if (['GRASA','PERDIDA DE GRASA','PERDIDA_GRASA'].includes(t)) return 'perdida_de_grasa';
  if (['MUSCULO','MUSCULATURA','GANANCIA MUSCULAR'].includes(t)) return 'musculatura';
  if (['RC','RECOMPOSICION','RECOMPOSICION CORPORAL'].includes(t)) return 'recomposicion_corporal';
  return t.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
};
const yesNo = v => {
  const t = upper(v);
  if (!t) return false;
  return ['SI','SÍ','TRUE','1','YES'].includes(t);
};
const salida = [];
for (const item of $input.all()) {
  const r = item.json;
  if (isBlank(r.nombre_completo) && isBlank(r.RUT) && isBlank(r.rut)) continue;
  const id = int(r.id_alumno);
  const rut = text(r.RUT ?? r.rut);
  // El nodo Postgres hace upsert por id_alumno; si no existe, n8n corta el nodo completo.
  if (!id) continue;
  const enfPrincipal = text(r.ENFOQUE ?? r.enfoque_principal);
  salida.push({ json: {
    id_alumno: id,
    nombre_completo: text(r.nombre_completo),
    rut,
    fecha_nacimiento: date(r.fecha_nacimiento),
    genero: text(r.genero),
    objetivo_id: int(r.objetivo_id),
    objetivo: objetivo(r.OBJETIVO ?? r.objetivo),
    enfoque_principal: enfPrincipal,
    enfoque_especifico: text(r.enfoque_especifico),
    debilidad: text(r.debilidad),
    prioridad_recomposicion: text(r.prioridad_recomposicion) || 'musculatura',
    frecuencia_semanal: int(r.frecuencia_semanal),
    nivel_experiencia: nivel(r.nivel_experiencia),
    fecha_ingreso: date(r.fecha_ingreso),
    estado_activo: bool(r.estado_activo) ?? true,
    evaluacion_inicial: bool(r.evaluacion_inicial) ?? false,
    plan: text(r.PLAN ?? r.plan),
    observaciones: text(r.observaciones)
  }});
}
return salida;

